import Button from '@mui/material/Button';
import '../styles/Cart.css';
import { useState } from 'react';

function Cart() {
    const tshirtPrice = 8, pullPrice = 10, pantalonPrice = 15;
    const [cart, updateCart] = useState(0);
    return (
        <div className='cart'>
            <h2>Panier</h2>
            <ul>
                <li>t-shirt : {tshirtPrice}€</li>
                <button onClick={() => updateCart(cart + 1)}>Ajouter un t-shirt</button>
                <li>pull : {pullPrice}€</li>
                <li>pantalon : {pantalonPrice}€</li>
            </ul>
            <div className="total">
                Total : {tshirtPrice * cart}€
            </div>
            <br />
            <button className="clear-cart" onClick={() => updateCart(0)}>
                Vider le panier
            </button>
        </div>
    );
}


export default Cart
